const e = $json;
const wfName = (e.workflow && e.workflow.name) || 'غير معروف';
const nodeName = (e.execution && e.execution.lastNodeExecuted) || 'غير معروف';
const errMsg = (e.execution && e.execution.error && e.execution.error.message) || 'لا توجد تفاصيل';
const execUrl = (e.execution && e.execution.url) || '';
const now = new Date().toISOString();
let text = '🚨 فشل تنفيذ أتمتة' + '

' + '📂 المسار: ' + wfName + '
' + '🔧 العقدة: ' + nodeName + '
' + '❌ الخطأ: ' + errMsg + '
' + '🕒 الوقت: ' + now;
if (execUrl) { text = text + '
🔗 ' + execUrl; }
return { json: { text } };
